{
    "description": "Normaliza logs de Juice Shop y detecta payloads comunes",
    "processors": [
        {
            "lowercase": {
                "field": "url.original",
                "ignore_missing": true
            }
        },
        {
            "script": {
                "source": "if (ctx?.url?.original != null) {if (ctx.url.original.contains(\"union select\") || ctx.url.original.contains(\" or 1=1\")) {ctx.threat = ctx.threat != null ? ctx.threat : [:];ctx.threat.indicator = ctx.threat.indicator != null ? ctx.threat.indicator : [:];ctx.threat.indicator.type = \"sql-injection\";}}"
            }
        }
    ]
}
